<template><div class="student-page"><header class="welcome"><div><p>STUDENT CENTER</p><h1>我的课程</h1><span>欢迎回来，继续完成你的团队作业</span></div><div class="welcome-icon">学</div></header><div v-if="errorMessage" class="error">{{ errorMessage }}</div><div v-if="loading" class="loading">正在加载课程…</div><div v-else class="course-grid"><article v-for="course in courses" :key="course.id" class="course-card" @click="router.push(`/student/course/${course.id}`)"><div class="course-cover"><span>{{ course.code?.slice(0,2) || 'GD' }}</span></div><div class="course-body"><small>{{ course.code }} · {{ course.term || '当前学期' }}</small><h2>{{ course.name }}</h2><div><span>{{ course.teacherName || '任课教师' }}</span><b>{{ course.studentCount || 0 }} 人</b></div></div></article><el-empty v-if="!courses.length" description="暂无课程" /></div></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElEmpty } from 'element-plus'; import { getCourses } from '@/api/student'; import { getErrorMessage } from '@/api/response'
const router=useRouter(); const courses=ref([]); const loading=ref(false); const errorMessage=ref(''); onMounted(async()=>{loading.value=true;try{courses.value=await getCourses()}catch(e){errorMessage.value=getErrorMessage(e,'课程加载失败')}finally{loading.value=false}})
</script>
<style scoped>.student-page{max-width:1120px;margin:0 auto}.welcome{display:flex;align-items:center;justify-content:space-between;margin-bottom:30px}.welcome p{margin:0 0 8px;color:#6b9ed8;font-size:11px;letter-spacing:1.5px}.welcome h1{margin:0 0 8px;color:#263b53;font-size:30px}.welcome span{color:#8795a6}.welcome-icon{display:grid;width:58px;height:58px;place-items:center;border-radius:16px;color:#fff;background:#6b9ed8;font-size:23px}.course-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.course-card{overflow:hidden;border:1px solid #e6edf2;border-radius:10px;background:#fff;box-shadow:0 3px 12px rgba(38,59,83,.06);cursor:pointer;transition:transform .2s}.course-card:hover{transform:translateY(-3px)}.course-cover{height:105px;padding:18px;background:linear-gradient(135deg,#356798,#6b9ed8)}.course-cover span{display:grid;width:46px;height:46px;place-items:center;border:1px solid #ffffff66;border-radius:12px;color:#fff;font-weight:600}.course-body{padding:18px}.course-body small{color:#9aa8b7}.course-body h2{margin:12px 0 18px;color:#263b53;font-size:19px}.course-body div{display:flex;justify-content:space-between;color:#8795a6;font-size:13px}.course-body b{color:#6b9ed8;font-weight:500}.loading,.error{padding:15px;border-radius:7px}.error{color:#b42318;background:#fff5f5}@media(max-width:800px){.course-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.course-grid{grid-template-columns:1fr}}</style>
